// LAB: Guard a conservation rule across real workers
// Two accounts begin with 100 each. Two workers make 100 opposite-direction transfers of one unit. Protect each complete transfer with the same mutex.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <mutex>

int main() {
    int first = 60, second = 40;
    std::mutex guard;
    {
        std::lock_guard<std::mutex> lock(guard);
        assert(first >= 10);
        first -= 10;
        second += 10;
        assert(first + second == 100);
    }
    std::cout << first << ' ' << second << '\n';
}

#include <cassert>
#include <iostream>
#include <mutex>
#include <future>



int main() {
    int first = 100, second = 100;
    std::mutex mutex;
    const auto move = [&](bool forward) {
        for(int i=0;i<100;++i) {
            std::lock_guard<std::mutex> lock(mutex);
            int& from = forward ? first : second;
            int& to = forward ? second : first;
            assert(from > 0);
            --from; ++to;
            assert(first+second == 200);
        }
    };
    auto a = std::async(std::launch::async,move,true);
    auto b = std::async(std::launch::async,move,false);
    a.get(); b.get();
    assert(first == 100 && second == 100);
    std::cout << "balances=" << first << ',' << second << " total=" << first+second << '\n';
}

